	router.GET(options.BaseURL+"/permissions", wrapper.ListPermissions, options.OperationMiddlewares["ListPermissions"]...)
	router.GET(options.BaseURL+"/role-templates", wrapper.ListTemplates, options.OperationMiddlewares["ListTemplates"]...)
	router.POST(options.BaseURL+"/role-templates", wrapper.CreateTemplate, options.OperationMiddlewares["CreateTemplate"]...)
	router.DELETE(options.BaseURL+"/role-templates/:id", wrapper.DeleteTemplate, options.OperationMiddlewares["DeleteTemplate"]...)
	router.GET(options.BaseURL+"/role-templates/:id", wrapper.GetTemplate, options.OperationMiddlewares["GetTemplate"]...)
	router.PUT(options.BaseURL+"/role-templates/:id", wrapper.UpdateTemplate, options.OperationMiddlewares["UpdateTemplate"]...)
