	router.DELETE(options.BaseURL+"/roles/:id", wrapper.DeleteRole, options.OperationMiddlewares["DeleteRole"]...)
	router.GET(options.BaseURL+"/roles/:id", wrapper.GetRole, options.OperationMiddlewares["GetRole"]...)
	router.PUT(options.BaseURL+"/roles/:id", wrapper.UpdateRole, options.OperationMiddlewares["UpdateRole"]...)
	router.GET(options.BaseURL+"/roles/:role_id/assignments", wrapper.ListAssignments, options.OperationMiddlewares["ListAssignments"]...)
